import re
_code = re.sub(r"#.*", "", student_code)
_lp = re.escape(nom)
sortie = student_output.strip()
probleme = None
if "..." in _code:
    probleme = "Il reste des `...` : remplacez-les par du code."
elif re.search(r"\bwhile\b", _code):
    probleme = "Ici, la boucle s'écrit avec `for` (pas de `while`)."
elif style == "elements":
    if re.search(r"\brange\s*\(", _code) or re.search(r"\b" + _lp + r"\s*\[", _code):
        probleme = f"Ici, on parcourt directement les éléments : `for {var} in {nom}:`, sans `range` ni `{nom}[i]`."
    elif not re.search(r"\bfor\s+\w+\s+in\s+" + _lp + r"\s*:", _code):
        probleme = f"Parcourez la liste avec `for {var} in {nom}:` (le nom `{var}` est au choix)."
elif not re.search(r"\bfor\s+\w+\s+in\s+range\s*\(\s*len\s*\(\s*" + _lp + r"\s*\)\s*\)\s*:", _code):
    if re.search(r"\brange\s*\(\s*\d", _code):
        probleme = f"Écrivez `range(len({nom}))` plutôt qu'un nombre : le programme doit marcher quelle que soit la longueur de la liste."
    else:
        probleme = f"Parcourez les indices avec `for i in range(len({nom})):`."
lignes = sortie.splitlines()
if probleme:
    check(False, probleme)
elif not sortie:
    check(False, "Votre programme n'affiche rien : utilisez `print(...)` dans la boucle.")
elif sortie != attendu.strip():
    if len(lignes) == 1 and len(data) > 1 and lignes[0] == str(ligne(data[-1])):
        check(False, "Seul le dernier élément s'affiche : le `print` doit être **dans** la boucle (décalé vers la droite, sous le `for`).")
    elif lignes == [str(k) for k in range(len(data))]:
        check(False, f"Vous affichez les indices 0, 1, 2… : affichez les éléments, `{nom}[i]`" + (f"[\"{cle}\"]" if mauvais_dict else "") + ".")
    elif lignes and all(l == str(data) for l in lignes):
        check(False, f"Vous affichez toute la liste à chaque tour : affichez seulement l'élément du tour.")
    elif mauvais_dict and lignes == [str(e) for e in data]:
        check(False, f"Vous affichez le dictionnaire entier : affichez seulement sa valeur pour la clé `\"{cle}\"`.")
    else:
        check(False, "Votre programme affiche `" + en_lignes(sortie) + "` alors qu'on attend `" + en_lignes(attendu)
              + "` (le / sépare les lignes).")
else:
    try:
        autre = rerun({nom: data2}).strip()
    except Exception:
        autre = None
    check(autre == attendu2.strip(), "Le bon résultat s'affiche, mais votre programme doit aller chercher les valeurs "
          f"dans `{nom}` au lieu de les écrire à la main : il sera testé avec une autre liste.")

