import copy
import re
_code = re.sub(r"#.*", "", student_code)
probleme = None
if "..." in _code:
    probleme = "Il reste des `...` : remplacez-les par du code."
elif re.search(r"\bwhile\b", _code):
    probleme = "Ici, la boucle s'écrit avec `for` (pas de `while`)."
elif not re.search(r"\bfor\b", _code):
    probleme = f"Parcourez la liste avec une boucle `for` : `for x in {lp}:` ou `for i in range(len({lp})):`."
else:
    for mot, raison in interdits:
        if re.search(r"\b" + mot + r"\s*\(", _code):
            probleme = f"`{mot}` est interdit : {raison}"
            break
fn = student.get(fname)
if probleme:
    check(False, probleme)
elif not callable(fn):
    check(False, f"la fonction `{fname}` doit être définie")
else:
    for args, attendu in cases:
        texte_appel = fname + "(" + ", ".join(repr(a) for a in args) + ")"
        try:
            obtenu = fn(*copy.deepcopy(args))
        except Exception as e:
            if type(e).__name__ == "TimeLimit":
                raise
            check(False, f"`{texte_appel}` provoque une erreur : {erreur(e)}" + (f". {conseil_erreur(e)}" if conseil_erreur(e) else ""))
            continue
        if obtenu is None:
            check(False, f"`{texte_appel}` ne renvoie rien : ajoutez `return {acc}` **après** la boucle (aligné avec le `for`).")
        elif obtenu != attendu and diagnostic(args, obtenu):
            check(False, f"`{texte_appel}` renvoie `{obtenu!r}` au lieu de `{attendu!r}` : " + diagnostic(args, obtenu))
        else:
            check_equal(obtenu, attendu, f"`{texte_appel}` renvoie `{obtenu!r}` au lieu de `{attendu!r}`")

